{{ config(materialized='incremental', unique_key=['order_id', 'line_no'], on_schema_change='fail') }}

SELECT
  CAST(index AS BIGINT) AS line_no,
  CAST(CASE
    WHEN (
      SUBSTRING(CAST(created_at AS VARCHAR) FROM 11) LIKE '%+%'
      OR SUBSTRING(CAST(created_at AS VARCHAR) FROM 11) LIKE '%-%'
    )
    OR UPPER(SUBSTRING(CAST(created_at AS VARCHAR) FROM 11)) LIKE '%Z%'
    THEN NULL
    ELSE created_at
  END AS TIMESTAMP) AT TIME ZONE 'Europe/Paris' AT TIME ZONE 'UTC' AS order_date,
  CAST(order_id AS TEXT) AS order_id,
  CAST(qty AS BIGINT) AS quantity,
  CAST(CAST(total AS DECIMAL(33, 4)) / qty AS DECIMAL(12, 4)) AS unit_price,
  CAST(ARRAY[] AS TEXT[]) AS _quality_flags,
  TRUE AS _quality_ok
FROM {{ source('bronze', 'shopify__order_lines') }}
